import { PROP_KINDS } from "./prop-models.ts";

export type ModelSource = "blender" | "code";

export type ModelRow = {
  /** What is drawn, in the player's words. */
  asset: string;
  /** Every id of it the game draws. */
  ids: readonly string[];
  /** Where the drawn geometry comes from today. */
  source: ModelSource;
  /** The code that builds it — the only builder of a `code` row, the
   * switched-off one of a `blender` row. */
  code: readonly string[];
  /** What puts it in the scene. */
  drawnBy: string;
  /** A modelled asset's Blender builder, its committed files (published
   * names under `pwa/models/`, and their shape as one pattern), and the
   * build switch that turns it back. */
  blender?: { builder: string; files: readonly string[]; pattern: string; switch: string };
  /** Anything a reader should know that the columns do not say. */
  note?: string;
};

const CAR_IDS = CARS.map((c) => c.id);

/** Every flora id a biome plants that is not a tree — read off the biomes'
 * own MIXES (`FloraMix`, id → weight: a community's `trees` and
 * `undergrowth`, a biome's shore, bank, highland and verge mixes), wherever
 * in a biome's row they sit. */
function undergrowth(): string[] {
  const ids = new Set<string>();
  const MIX = /^(trees|undergrowth)$|Trees$|Cover$/;
  const walk = (o: unknown): void => {
    if (!o || typeof o !== "object") return;
    for (const [k, v] of Object.entries(o)) {
      if (MIX.test(k) && v && typeof v === "object") {
        for (const id of Object.keys(v)) if (!(id in TREE_ROW)) ids.add(id);
      } else walk(v);
    }
  };
  for (const b of Object.values(BIOMES)) walk(b);
  return [...ids].sort();
}

